steps.script:
GameState.state["factions"]["1"]["detachment"] = "Blitz Brigade"
StratagemManager.load_faction_stratagems_for_player(1)
var spots = {"U_CUSTODIAN_GUARD_E": Vector2(40, 52), "U_BATTLEWAGON_A": Vector2(40, 44.5)}
for uid in spots:
	var u = GameState.state["units"][uid]
	var c = Vector2.ZERO
	for m in u["models"]:
		c += Vector2(float(m["position"]["x"]), float(m["position"]["y"]))
	c /= u["models"].size()
	var d = spots[uid] * 40.0 - c
	for m in u["models"]:
		m["position"] = {"x": float(m["position"]["x"]) + d.x, "y": float(m["position"]["y"]) + d.y}
GameState.state["players"]["1"]["cp"] = 4
GameState.state["players"]["2"]["cp"] = 0
SceneRefs.main()._recreate_unit_visuals()
return StratagemManager.find_faction_stratagem_by_name(1, "IMPENDING KRUNCH")

for c in tree.root.get_children():
	if c is Window and c != tree.root:
		c.hide()
		c.queue_free()
return true

var ph = PhaseManager.get_current_phase_instance()
if ph.awaiting_ability_reroll:
	ph.execute_action({"type": "DECLINE_ABILITY_REROLL", "actor_unit_id": "U_BATTLEWAGON_A", "player": 1})
if ph.awaiting_reroll_decision:
	ph.execute_action({"type": "DECLINE_COMMAND_REROLL", "actor_unit_id": "U_BATTLEWAGON_A", "player": 1})
for c in tree.root.get_children():
	if c is Window and c != tree.root:
		c.hide()
		c.queue_free()
return int(ph.pending_charges["U_BATTLEWAGON_A"]["distance"])

var ph = PhaseManager.get_current_phase_instance()
var mv = AIDecisionMaker._compute_charge_move(GameState.create_snapshot(), "U_BATTLEWAGON_A", 5, ["U_CUSTODIAN_GUARD_E"], 1)
if str(mv.get("type", "")) != "APPLY_CHARGE_MOVE":
	return "NO_MOVE"
mv["player"] = 1
var r = NetworkIntegration.route_action(mv)
return r.get("success", false)

var r = GameState.get_unit("U_BATTLEWAGON_A")["flags"]["ork11e_impending_krunch"][0]
var d = r["dice"]
if int(r["total"]) != int(d[0]) + int(d[1]) - 1:
	return "MODIFIER_MISSING"
var shocked = bool(GameState.get_unit("U_CUSTODIAN_GUARD_E")["flags"].get("battle_shocked", false))
return shocked == (not bool(r["passed"]))

for c in tree.root.get_children():
	if c is Window and c != tree.root:
		c.hide()
		c.queue_free()
SceneRefs.main()._recreate_unit_visuals()
return true
